// Prüft den Eingang, bevor ein Sprachmodell Geld kostet
// Harte Fehler brechen ab, weiche laufen mit bis ins Compliance-Audit
const eintraege = $input.all().map(i => i.json);
const hart = [];
const weich = [];

if (eintraege.length === 0) hart.push('Keine Potenziale im Konzept (weder potenziale[] noch use_cases[])');

const KP = /^KP-(0[1-9]|10)$/;
const TP = /^KP-(0[1-9]|10)\.TP-[1-9][0-9]?$/;

eintraege.forEach((e, i) => {
  const wo = `Eintrag ${i + 1}`;

  if (e.ist_json === false) hart.push(`${wo}: Datei ist kein gültiges JSON (${e.parse_fehler || 'ohne Angabe'})`);
  if (!e.use_case_id) hart.push(`${wo}: keine ID (potenzial_id oder use_case_id)`);
  if (!e.use_case_titel) hart.push(`${wo}: kein Titel`);

  const text = String(e.fachliche_beschreibung || '');
  if (text.length < 300) hart.push(`${wo}: Beschreibung zu kurz (${text.length} von 300 Zeichen)`);

  // Auflage BC0 vom 24.08.2026
  if (!e.kp_id) hart.push(`${wo}: kp_id fehlt`);
  else if (!KP.test(e.kp_id)) hart.push(`${wo}: kp_id „${e.kp_id}“ passt nicht zu KP-01 bis KP-10`);

  const tps = e.teilprozess_ids || [];
  if (tps.length === 0) {
    weich.push(`${wo}: keine Teilprozess-Kennung`);
  } else if (e.tp_herkunft === 'aus dem Text gelesen') {
    weich.push(`${wo}: Teilprozess ${tps.join(', ')} nur aus dem Text gelesen, nicht aus einem Feld`);
  }
  tps.forEach(t => { if (!TP.test(t)) hart.push(`${wo}: Teilprozess „${t}“ passt nicht zu KP-XX.TP-Y`); });

  const vision = String(e.to_be_vision || '');
  if (!vision) weich.push(`${wo}: kein Soll-Zustand`);
  else if (vision.length < 400) weich.push(`${wo}: Soll-Zustand nur ${vision.length} Zeichen (Kurzfassung)`);

  if (!(e.fachliche_anforderungen || []).length) weich.push(`${wo}: keine fachlichen Anforderungen`);
  if (!(e.akzeptanzkriterien_geschaeftlich || []).length) weich.push(`${wo}: keine Akzeptanzkriterien, BC3 muss sie selbst formulieren`);
  if (!(e.betroffene_systeme || []).length) weich.push(`${wo}: keine betroffenen Systeme`);
});

// Text „Eingangsprüfung fehlgeschlagen“ nicht ändern, BC3-99 erkennt daran die Art
if (hart.length) {
  throw new Error('Eingangsprüfung fehlgeschlagen: ' + hart.join(' | '));
}

return $input.all().map(i => ({
  json: { ...i.json, eingang_befunde: weich, eingang_geprueft: true },
}));

// Ergebnis in den Umschlag, ab hier reisen alle Stufen mit demselben Objekt

// Reihenfolge: erst die Empfehlung von BC2 (gesamtempfehlung), dann rang
const empfehlung = $input.all()
  .map(i => i.json.reihenfolge_empfehlung)
  .find(x => Array.isArray(x) && x.length) || [];
const platz = new Map(empfehlung.map((id, i) => [String(id), i]));

// Widersprechen sich Empfehlung und rang, kommt das ins Protokoll (Rückfrage an BC2)
const kennung = e => String(e.potenzial_id ?? e.use_case_id ?? '');
const widerspruch = (() => {
  if (empfehlung.length < 2) return null;
  const nachRang = [...$input.all().map(i => i.json)]
    .sort((a, b) => (a.rang ?? 999) - (b.rang ?? 999)).map(kennung);
  const nachEmpf = empfehlung.map(String).filter(id => nachRang.includes(id));
  if (nachRang.join() === nachEmpf.join()) return null;
  return `Reihenfolge von BC2 widersprüchlich: Empfehlung ${nachEmpf.map(x => x.slice(-4)).join(' vor ')}, `
    + `rang ${nachRang.map(x => x.slice(-4)).join(' vor ')}, BC3 folgt der Empfehlung, bei BC2 nachfragen`;
})();

function nachReihenfolge(a, b) {
  const pa = platz.get(String(a.potenzial_id ?? a.use_case_id));
  const pb = platz.get(String(b.potenzial_id ?? b.use_case_id));
  if (pa != null && pb != null) return pa - pb;
  if (pa != null) return -1;
  if (pb != null) return 1;
  return (a.rang ?? 999) - (b.rang ?? 999);
}

// Reihenfolge bleibt ab hier fest, BC3-20 ordnet Epic i dem Potenzial i zu
const eintraege = $input.all().map(i => i.json).sort(nachReihenfolge);
const erster = eintraege[0] || {};
const quelle = $('Datei holen (BC3-11)').first().json;
const rein = $('Vom Orchestrator aufgerufen').first().json;
const umschlag = rein.umschlag || {};
// Gate 1 und Kennungen stehen an jedem Eintrag, im Umschlag nur einmal
const potenziale = eintraege.map(({ gate1_auswahl, kette_ids, ...rest }) => rest);

return [{
  json: {
    lauf_id: rein.lauf_id,
    umschlag: {
      ...umschlag,
      quelle: { art: 'github', pfad: quelle.pfad, url: quelle.url, dateiname: quelle.dateiname },
      ids: erster.kette_ids || null,
      konzept: {
        konzept_id: erster.konzept_id,
        schema_version: erster.schema_version,
        kp_id: erster.kp_id,
        unternehmen: erster.unternehmen || null,
        prozess: erster.prozess,
        schmerzpunkte: erster.schmerzpunkte || [],
        teilprozess_ids: [...new Set(eintraege.flatMap(e => e.teilprozess_ids || []))],
        warnung: eintraege.map(e => e.warnung).find(Boolean) || null,
        gate1: erster.gate1_auswahl || null,
        // Kurzfassung für Gate 2, Protokoll und Compliance
        ist_vorlaeufig: eintraege.some(e => e.ist_vorlaeufig === true),
        annahmen: [...new Set(eintraege.flatMap(e => e.annahmen || []))],
      },
      potenziale,
      protokoll: [...(umschlag.protokoll || []), {
        stufe: 'BC3-10 Konzept einlesen',
        zeitpunkt: new Date().toISOString(),
        status: 'ok',
        befunde: [
          ...(erster.gate1_auswahl?.befunde || []),
          ...(widerspruch ? [widerspruch] : []),
          ...(erster.eingang_befunde || []),
        ],
      }],
    },
  },
}];

// Ein Item je Potenzial, liest Vertrag v1 bis v3.1
const item = $input.first();
const binaryKey = Object.keys(item.binary || {})[0];
if (!binaryKey) throw new Error('Keine Datei erhalten');

const binData = item.binary[binaryKey];
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
let text = buffer.toString('utf-8');
if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1); // BOM entfernen
text = text.trim();

let konzept = null;
try {
  konzept = JSON.parse(text);
} catch (e) {
  // Aus Word kopiert: „…" mit geradem Schlusszeichen beendet den String zu früh
  const fixed = text.replace(/„([^"„]{1,200}?)"/g, '„$1“');
  try {
    konzept = JSON.parse(fixed);
  } catch (e2) {
    return [{
      json: {
        use_case_id: 'unbekannt',
        titel: 'Kein gültiges JSON',
        konzept_text_raw: text,
        ist_json: false,
        parse_fehler: e2.message,
        original_filename: binData.fileName
      }
    }];
  }
}

// v1.0: use_cases[] mit use_case_id, ab v2: potenziale[] mit potenzial_id
const eintraege = konzept.potenziale || konzept.use_cases || [];
const kp_id = konzept.kontext?.kp_id || null;

const kontext_kompakt = {
  konzept_id: konzept.konzept_id,
  schema_version: konzept.schema_version,
  kp_id: kp_id,
  prozess: konzept.kontext?.prozess_kurzbeschreibung,
  unternehmen: konzept.kontext?.unternehmen || null,
  schmerzpunkte: konzept.kontext?.hauptschmerzpunkte
};

// Teilprozess-Kennungen auch aus Freitext lesen (v2.0 hat kein eigenes Feld)
const TP_MUSTER = /\bKP-(?:0[1-9]|10)\.TP-[1-9][0-9]?\b/g;
function tpAusText(objekt) {
  return [...new Set(String(JSON.stringify(objekt || {})).match(TP_MUSTER) || [])];
}

// Warnkasten (Zeilen mit >) abtrennen, damit er nicht in die Stories wandert
function warnkastenTrennen(text) {
  const t = String(text || '');
  const zeilen = t.split('\n');
  const warn = [];
  let i = 0;
  while (i < zeilen.length && (zeilen[i].startsWith('>') || zeilen[i].trim() === '')) {
    if (zeilen[i].startsWith('>')) warn.push(zeilen[i].replace(/^>\s?/, ''));
    i++;
  }
  return { warnung: warn.join(' ').trim() || null, rest: zeilen.slice(i).join('\n').trim() };
}

// Ab v3.1 ist die potenzial_id die Saat für die Epic-ID, ältere behalten ihre IDs
const MIT_KETTE = Number(konzept.schema_version) >= 3.1;

return eintraege.map(uc => {
  // Teilprozess-Kennungen: Auflage BC0 vom 24.08.2026
  const eigene = uc.betroffene_teilprozess_ids || [];
  const gefunden = eigene.length ? [] : [...tpAusText(uc), ...tpAusText(konzept.kontext)];
  const tp_ids = eigene.length ? eigene : gefunden;
  const tp_herkunft = eigene.length ? 'feld' : (gefunden.length ? 'aus dem Text gelesen' : 'keine');

  const roh = uc.fachliche_beschreibung || uc.beschreibung;
  const geteilt = warnkastenTrennen(roh);
  const ersetzt = Array.isArray(uc.ersetzt_potenzial_ids) ? uc.ersetzt_potenzial_ids.map(String) : [];
  return {
    json: {
      konzept_id: kontext_kompakt.konzept_id,
      schema_version: kontext_kompakt.schema_version,
      prozess: kontext_kompakt.prozess,
      unternehmen: kontext_kompakt.unternehmen,
      schmerzpunkte: kontext_kompakt.schmerzpunkte,
      original_filename: binData.fileName,
      // Reihenfolge laut BC2 (gesamtempfehlung), wird in Umschlag füllen genutzt
      reihenfolge_empfehlung: konzept.gesamtempfehlung?.reihenfolge_potenzial_ids || [],
      reihenfolge_begruendung: konzept.gesamtempfehlung?.begruendung || null,

      // Kennungen, gehen bis ins Ticket
      kp_id: uc.kp_id || kontext_kompakt.kp_id,
      teilprozess_ids: tp_ids,
      referenz_id: tp_ids.length ? tp_ids[0] : (uc.kp_id || kontext_kompakt.kp_id),

      use_case_id: uc.use_case_id || uc.potenzial_id,
      use_case_titel: uc.titel,
      rang: uc.potenzialrang ?? uc.rang, // ab v3.0 potenzialrang
      ersetzt_potenzial_ids: ersetzt,
      // Saat für die Epic-ID in BC3-40: Vorgänger, sonst das Potenzial selbst (#242)
      id_saat: MIT_KETTE ? String(ersetzt[0] || uc.potenzial_id || uc.use_case_id) : null,
      fachliche_beschreibung: geteilt.rest || roh,
      warnung: geteilt.warnung,
      tp_herkunft,
      to_be_vision: uc.to_be_vision || uc.potenzielle_loesung?.to_be_kurz || null,
      tech_stack: uc.tech_stack_empfehlung || uc.potenzielle_loesung?.tech_stack_empfehlung || [],
      betroffene_systeme: uc.betroffene_systeme || [],
      betroffene_prozessschritte: uc.betroffene_prozessschritte || [],
      voraussetzungen: uc.voraussetzungen || [],
      fachliche_anforderungen: uc.fachliche_anforderungen || [],
      akzeptanzkriterien_geschaeftlich: uc.akzeptanzkriterien_geschaeftlich || [],

      risiken: uc.risiken || [],                                  // für BC3-30
      annahmen: uc.value?.annahmen || uc.roi?.annahmen || [],     // für Gate 2

      // Vorläufige Zahlen erkennen: value_quelle, [VORLAEUFIG] im Titel oder Text
      value_quelle: uc.value?.value_quelle || uc.roi?.roi_quelle || null,
      ist_vorlaeufig: ['annahme', 'default'].includes(uc.value?.value_quelle)
        || /\[\s*VORL[AÄ]UFIG\s*\]/i.test(String(uc.titel || ''))
        || /\[\s*VORL[AÄ]UFIG\s*\]/i.test(String(uc.beschreibung || uc.fachliche_beschreibung || ''))
    }
  };
});

// Nur Potenziale, die BC2 an Gate 1 freigegeben hat (A5), dazu die Kennungen der Kette (A6)
const items = $('Potenziale auslesen').all();
const potenziale = items.map(i => i.json);
// Kaputtes JSON meldet "Eingang prüfen", hier nichts aussortieren
if (potenziale.some(e => e.ist_json === false)) return items;

const p = $input.first().json || {};
const lesbar = !p.error && !!p.priorisierung_id;
const gate1 = lesbar ? (p.gate1 || {}) : {};
const status = gate1.status || null;
const frei = (gate1.approved_potenzial_ids || []).map(String);
const kennung = e => String(e.use_case_id ?? '');
const befunde = [];
let behalten = potenziale;

// Text „Eingangsprüfung fehlgeschlagen“ nicht ändern, BC3-99 erkennt daran die Art
if (status === 'rejected') {
  throw new Error('Eingangsprüfung fehlgeschlagen: Gate 1 abgelehnt (' + (gate1.entschieden_am || 'ohne Datum') + ')');
}
if (status === 'approved' && frei.length) {
  behalten = potenziale.filter(e => frei.includes(kennung(e)));
  if (!behalten.length) {
    throw new Error('Eingangsprüfung fehlgeschlagen: keines der an Gate 1 freigegebenen Potenziale steht im Konzept (' + frei.join(', ') + ')');
  }
  if (behalten.length < potenziale.length) {
    befunde.push(behalten.length + ' von ' + potenziale.length + ' Potenzialen an Gate 1 freigegeben, nur diese bearbeitet');
  }
} else if (status === 'approved') {
  befunde.push('Gate 1 freigegeben ohne Liste der Potenziale, alle bearbeitet');
} else if (lesbar) {
  befunde.push('Gate 1 nicht freigegeben (' + (status || 'ohne Status') + '), alle Potenziale bearbeitet, nur für Tests');
} else {
  befunde.push('Keine Priorisierung im Ordner des Konzepts, alle Potenziale bearbeitet, nur für Tests');
}

const gate1_auswahl = {
  status,
  entschieden_am: gate1.entschieden_am || null,
  freigegeben: behalten.map(kennung),
  nicht_freigegeben: potenziale.filter(e => !behalten.includes(e)).map(kennung),
  befunde,
};
// anfrage_id liefert BC2 nicht, bleibt leer
const kette_ids = {
  company_id: lesbar ? (p.company_id || null) : null,
  anfrage_id: null,
  paket_id: lesbar ? (p.paket_id || null) : null,
  priorisierung_id: lesbar ? (p.priorisierung_id || null) : null,
  konzept_id: potenziale[0]?.konzept_id || null,
  process_id: behalten[0]?.kp_id || null,
  sub_process_id: [...new Set(behalten.flatMap(e => e.teilprozess_ids || []))].join(', ') || null,
};

return behalten.map(e => ({ json: { ...e, gate1_auswahl, kette_ids } }));
